 async function checkCentralChanges(){if(!context||document.hidden||centralRefreshInFlight)return;centralRefreshInFlight=true;try{const [latestAppointments,latestSettings,latestInvoice]=await Promise.all([db.from('appointments').select('updated_at').eq('organization_id',context.organizationId).eq('clinic_id',context.clinicId).order('updated_at',{ascending:false}).limit(1).maybeSingle(),db.from('clinic_settings').select('updated_at').eq('organization_id',context.organizationId).eq('clinic_id',context.clinicId).order('updated_at',{ascending:false}).limit(1).maybeSingle(),db.from('sales_invoices').select('created_at,status,total').eq('organization_id',context.organizationId).eq('clinic_id',context.clinicId).order('created_at',{ascending:false}).limit(1).maybeSingle()]);if(!latestAppointments.error){const revision=latestAppointments.data?.updated_at||'';if(lastAppointmentRevision&&revision&&revision!==lastAppointmentRevision){appointmentListCache.clear();agendaFrame.contentWindow?.postMessage({type:'atlas:central-appointments-changed'},'*')}lastAppointmentRevision=revision}if(!latestSettings.error){const revision=latestSettings.data?.updated_at||'';if(lastSettingsRevision&&revision&&revision!==lastSettingsRevision)agendaFrame.contentWindow?.postMessage({type:'atlas:central-settings-changed'},'*');lastSettingsRevision=revision}if(!latestInvoice.error){const revision=JSON.stringify(latestInvoice.data||{});if(lastInvoiceRevision&&revision&&revision!==lastInvoiceRevision){agendaFrame.contentWindow?.postMessage({type:'atlas:central-invoices-changed'},'*');fichaFrame.contentWindow?.postMessage({type:'atlas:central-invoices-changed'},'*')}lastInvoiceRevision=revision}}finally{centralRefreshInFlight=false}}
